import math

def is_prime(number: int) -> bool:
    """
    Determine whether a number is prime.
    """
    if number <= 1:
        return False
    if number <= 3:
        return True
    if number % 2 == 0 or number % 3 == 0:
        return False

    limit = int(math.isqrt(number))
    for divisor in range(5, limit + 1, 6):
        if number % divisor == 0 or number % (divisor + 2) == 0:
            return False

    return True
